sealed interface ApiError {
    data class Invalid(val errors: NonEmptyList<PaymentError>) : ApiError
    data class Failed(val error: PaymentError) : ApiError
}

fun handle(request: PaymentRequest, gateway: Gateway): Either<ApiError, Receipt> = either {
    val valid = validate(request).mapLeft(ApiError::Invalid).bind()   // every form error at once
    pay(valid, gateway).mapLeft(ApiError::Failed).bind()               // the first business failure
}

