sealed interface ApiError {}
record InvalidRequest(List<PaymentError> errors) implements ApiError {}
record Failed(PaymentError error) implements ApiError {}

Outcome<ApiError, Receipt> handle(PaymentRequest request, Gateway gateway) {
    return switch (validate(request)) {
        case Invalid<ValidPayment> invalid -> new Err<>(new InvalidRequest(invalid.errors()));   // every form error
        case Valid<ValidPayment> valid -> switch (pay(valid.value(), gateway)) {                 // the first business failure
            case Ok<PaymentError, Receipt> ok -> new Ok<>(ok.value());
            case Err<PaymentError, Receipt> err -> new Err<>(new Failed(err.error()));
        };
    };
}

