Outcome<PaymentError, String> charge(Http http, String body) throws IOException {
    try {
        return new Ok<>(http.post(body));
    } catch (SocketTimeoutException e) {
        return new Err<>(new ProviderUnavailable());   // the one failure with a business meaning
    }                                                  // other exceptions propagate: a bug stays a bug
}

